mvn spring-boot:run
curl "localhost:8080/bakery/cost?item=flour&kg=10"
curl localhost:8080/bakery/status/sugar
curl localhost:8080/bakery/safe-cost/saffron
curl -X POST "localhost:8080/bakery/restock?item=butter&kg=2"
```

